package java.io;
public class DataInputStream extends InputStream {
    protected final InputStream in; public DataInputStream(InputStream in){this.in=in;} public int read() throws IOException{return in.read();} public int read(byte[] b,int off,int len)throws IOException{return in.read(b,off,len);} public void close() throws IOException{in.close();} public int available()throws IOException{return in.available();}
    public void readFully(byte[] b)throws IOException{readFully(b,0,b.length);} public void readFully(byte[] b,int off,int len)throws IOException{while(len>0){int n=in.read(b,off,len);if(n<0)throw new EOFException();off+=n;len-=n;}}
    public boolean readBoolean()throws IOException{return readUnsignedByte()!=0;} public byte readByte()throws IOException{return (byte)readUnsignedByte();} public int readUnsignedByte()throws IOException{int v=read();if(v<0)throw new EOFException();return v;} public short readShort()throws IOException{return (short)readUnsignedShort();} public int readUnsignedShort()throws IOException{return (readUnsignedByte()<<8)|readUnsignedByte();} public char readChar()throws IOException{return (char)readUnsignedShort();} public int readInt()throws IOException{return (readUnsignedByte()<<24)|(readUnsignedByte()<<16)|(readUnsignedByte()<<8)|readUnsignedByte();} public long readLong()throws IOException{return ((long)readInt()<<32)|(readInt()&0xffffffffL);} public float readFloat()throws IOException{return Float.intBitsToFloat(readInt());} public double readDouble()throws IOException{return Double.longBitsToDouble(readLong());} public int skipBytes(int n)throws IOException{return (int)in.skip(n);}
    public String readUTF()throws IOException{int n=readUnsignedShort();byte[] b=new byte[n];readFully(b);StringBuilder out=new StringBuilder();for(int i=0;i<n;){int c=b[i++]&255;if(c>0&&c<128)out.append((char)c);else if((c&224)==192&&i<n){int d=b[i++]&255;if((d&192)!=128)throw new IOException("bad modified UTF-8");out.append((char)(((c&31)<<6)|(d&63)));}else if((c&240)==224&&i+1<n){int d=b[i++]&255,e=b[i++]&255;if((d&192)!=128||(e&192)!=128)throw new IOException("bad modified UTF-8");out.append((char)(((c&15)<<12)|((d&63)<<6)|(e&63)));}else throw new IOException("bad modified UTF-8");}return out.toString();}
}
